function pieceProducts(n: number, queries: number[][]): number[] {
  const M = 1000000007n;
  const pieces: bigint[] = [];
  for (let bit = 0; bit < 31; bit++) if (Math.floor(n / 2 ** bit) % 2 === 1) pieces.push(2n ** BigInt(bit));
  return queries.map(([l, r]) => {
    let prod = 1n;
    for (let i = l; i <= r; i++) prod = (prod * pieces[i]) % M;
    return Number(prod);
  });
}

