        M = 10**9 + 7
        pieces = [1 << b for b in range(31) if n >> b & 1]
        out = []
        for l, r in queries:
            prod = 1
            for i in range(l, r + 1):
                prod = prod * pieces[i] % M
            out.append(prod)
        return out

