function pieceProducts(n: number, queries: number[][]): number[] {
  const M = 1000000007;
  const pre = [0];
  for (let bit = 0; bit < 31; bit++) {
    if (Math.floor(n / 2 ** bit) % 2 === 1) pre.push(pre[pre.length - 1] + bit);
  }
  const top = pre[pre.length - 1];
  const pow2 = [1];
  for (let e = 1; e <= top; e++) pow2.push((pow2[e - 1] * 2) % M); // doubling stays exact
  return queries.map(([l, r]) => pow2[pre[r + 1] - pre[l]]);
}

